css:
.content {
    max-width: 800px;
    margin: 5px auto;
    padding: 10px;
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    text-align: right;
}

h1 {
    font-family: Tajawal, Montserrat, sans-serif;
    color: #333;
    text-align: center;
    font-size: 20px;
    margin: 5px 0;
}

h2 {
    font-family: Tajawal, Montserrat, sans-serif;
    color: #666;
    font-size: 16px;
    margin-top: 5px;
    margin-bottom: 5px;
}

p {
    line-height: 1.4;
    margin: 5px 0;
}

table {
    width: 100%;
    margin-top: 5px;
    border-collapse: collapse;
    border-radius: 8px;
    overflow: hidden;
}

th, td {
    border: 1px solid #ddd;
    padding: 4px;
    text-align: center;
    background-color: #f9f9f9;
}

th {
    background-color: #eee;
    color: #333;
    font-weight: 700;
}
.info-table {
    border-collapse: collapse;
    width: 100%;
}

.info-table td {
    border: none; /* Remove borders */
    background-color: transparent; /* Remove background color */
    padding: 1px; /* Ensure padding remains consistent */
}

.left-cell {
    width: 50%;
    text-align: right;
}

.right-cell {
    width: 50%;
    text-align: left;
}


ul {
    list-style-type: none;
    padding: 0;
}

ul li {
    background: #f9f9f9;
    margin: 1px 0;
    padding: 5px;
    border-left: 5px solid #ccc;
}

.footer {
    margin-top: 1px;
    text-align: left;
    font-size: 14px;
    color: #555;
}

.signature-line {
    border-bottom: 1px solid #000;
    width: 200px;
    display: inline-block;
    margin-top: 5px;
}
